acceptanceTests.acceptance.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { median } from './median.mjs';
test('empty', () => assert.equal(median([]), null));
test('single', () => assert.equal(median([7]), 7));
test('numeric ordering', () => assert.equal(median([2, 11, 3]), 3));
test('even average', () => assert.equal(median([9, 1, 7, 3]), 5));
test('negative numbers', () => assert.equal(median([-1, -20, -3]), -3));
test('fractional values', () => assert.equal(median([1.5, 0.5, 3.5, 2.5]), 2));
test('duplicates', () => assert.equal(median([4, 4, 4, 4]), 4));
test('input immutability', () => { const values = [3, 1, 2]; const before = [...values]; median(values); assert.deepEqual(values, before); });
